// golfing 625 chars https://shadertoy.com/view/XljSW3
// see also version with continuous transition: https://www.shadertoy.com/view/wcl3Wf

// -9 by Xor -4 by Fab
void mainImage( out vec4 o, vec2 U )
{
    float s = iResolution.y, i;
    vec2 r, k, v; r.y++, k=r--; // r=(0,1) k=(-1,0)
    for (v=ceil(U = U/s-.5+.3*r); i++ < mod(iTime,7.); s/=2.) 
        U += U+.5-v,
        r = v==k ? -r.yx : k,   
        U.x *= 1. - 2.*v.x,
        v = ceil( U -= (U.yx+U)*v.y );

    k = abs(U);
    o = vec4(.2,.7,.07,1)/s
      *( ceil(dot(U,r*step(k,1.-k))) / (k*r.y-k.y*r).x + v.x / k.y );
}





/** // 294ch: -1 by jt, -34 by SnoopethDuckDuck, -4 by Fab

void mainImage( out vec4 o, vec2 U )
{
    float s = iResolution.y, i, z;
    U /= s; U.x -= .3;    
    o = abs(U.x-.5) < .5 ? vec4(.2,.7,0,1) : z*o;
    vec2 r, B, k; r.x--;
    for (k.y++; i++ < mod(iTime,7.); s*=.5) 
        B = round(U),
        U += U - B,
        r = B == k ? -r.yx : k,
        B.x>z ? U.x = 1.-U.x :z,   // sym
        B.y>z ? U   = 1.-U.yx:U;   // rot+sym   

    o *= ( ceil(dot(U-=.5,r))/abs(U*r.y-U.y*r)
         + ceil(U)/abs(U.y) ).x / s;
}






/** // - 123ch by SnoopethDuckDuck

void mainImage( out vec4 o, vec2 U )
{
    float s = 1./iResolution.y, i, z;
    U *= s; 
    vec2 r, k; r.x--;
    for (U.x -= .3; i++ < mod(iTime,7.); s+=s) {
        bool x = .5 < U.x, 
             y = .5 < U.y;
        U += U - vec2(x,y);
        r = !x && y ? -r.yx : vec2(0,1);       
        x ? U.x = 1.-U.x :z;   // sym
        y ? U   = 1.-U.yx:U;   // rot+sym        
    }

    k = min(U,1.-U);
    U -= .5;
    o = vec4(.3,1,.1,1);
    o *= k.x>z&&k.y>z 
       ? ( dot(U,r) > z ? .7*s / abs(U.x*r.y-U.y*r.x) : z )
       + (      U.x > z ? .7*s / abs(U.y) : z )
       : z;
}





/** // 456 chars

#define P(l) ( dot(U-P,l) > 0. ?  .7*s/H / abs( dot( U-P, vec2(-l.y,l) )) : 0. )


void mainImage( out vec4 o, vec2 U )
{
    float H = iResolution.y, s=1., i;
    U /= H; U.x -= .3;
    vec2 S, k, P = k+.5,
  // I=vec2(1,0), J=I.yx, l=-I, r=l;
     I,J,l,r; I.x++, J.y++,  r = l=-I;

    for (; i < 9.; i++ ) {                 // recursion
        if ( i > mod(iTime,7.) ) break;    // max depth                
        bvec2 c = bvec2(S = step(.5,U) );  // select child
        U += U - S;                        // go to new local frame
        l = c.x ? c.y ? -J : -I            // node left segment
                : c.y ?  l :  J;
        r =  c.x==c.y ?  I : c.y ? -J : J; // node right segment
        // the heart of Hilbert curve : 
        c.x ? U.x = 1.-U.x,  l.x=-l.x,  r.x=-r.x,  k=l,l=r,r=k :r;  // sym
        c.y ? U   = 1.-U.yx, l  =-l.yx, r  =-r.yx              :r;  // rot+sym
        s += s;
    }

    k = min(U,1.-U);                       // black outside square
    o = min(k.x,k.y) > 0. ? ( P(l) + P(r) ) * vec4(.3,1,.1,1) : o*0.;
}

